package dev.eugheist.ttmodern;
/** Original one-world-block-per-screen-pixel destination map. */
public final class WarpGateDestinations extends net.minecraft.client.gui.screens.Screen {
 final WarpGateEntity gate;double originX,originZ;int ticks;
 public WarpGateDestinations(WarpGateEntity gate){super(net.minecraft.network.chat.Component.translatable("ttmisc.destinations"));this.gate=gate;}
 @Override protected void init(){center(gate.getBlockPos());}
 void center(net.minecraft.core.BlockPos pos){originX=pos.getX()-width/2;originZ=pos.getZ()-height/2;}
 boolean visible(net.minecraft.world.item.ItemStack pearl){return !pearl.isEmpty()&&SkyPearlData.attuned(pearl)&&gate.getLevel()!=null&&SkyPearlData.dimension(pearl).equals(gate.getLevel().dimension().location());}
 @Override public boolean isPauseScreen(){return false;}
 @Override public void tick(){ticks++;if(gate.isRemoved())onClose();}
 @Override public boolean mouseDragged(double x,double y,int button,double dx,double dy){if(button==0){originX-=dx;originZ-=dy;return true;}return super.mouseDragged(x,y,button,dx,dy);}
 @Override public boolean keyPressed(int key,int scan,int modifiers){if(key==org.lwjgl.glfw.GLFW.GLFW_KEY_SPACE){center(gate.getBlockPos());return true;}int index=key==org.lwjgl.glfw.GLFW.GLFW_KEY_0?9:key-org.lwjgl.glfw.GLFW.GLFW_KEY_1;if(index>=0&&index<10){var pearl=gate.inventory.getStackInSlot(index);if(visible(pearl))center(SkyPearlData.position(pearl));return true;}return super.keyPressed(key,scan,modifiers);}
 @Override public boolean mouseClicked(double x,double y,int button){if(button==0&&hasControlDown())for(int i=0;i<10;i++){var pearl=gate.inventory.getStackInSlot(i);if(!visible(pearl))continue;var pos=SkyPearlData.position(pearl);double px=pos.getX()-originX,pz=pos.getZ()-originZ;if(x>=px-4&&x<=px+4&&y>=pz-4&&y<pz+4){net.neoforged.neoforge.network.PacketDistributor.sendToServer(new WarpGateNetwork.Teleport(gate.getBlockPos(),i));onClose();return true;}}return super.mouseClicked(x,y,button);}
 @Override public void render(net.minecraft.client.gui.GuiGraphics g,int mx,int my,float partial){
  int rgb=java.awt.Color.HSBtoRGB((float)(Math.sin(ticks/150d)+.5),.5f,.4f);g.setColor((rgb>>16&255)/255f,(rgb>>8&255)/255f,(rgb&255)/255f,1);g.blit(net.minecraft.resources.ResourceLocation.withDefaultNamespace("textures/entity/end_portal.png"),0,0,0,0,width,height,256,256);g.setColor(1,1,1,1);
  int gx=(int)(gate.getBlockPos().getX()-originX),gz=(int)(gate.getBlockPos().getZ()-originZ);int alpha=(int)(((Math.sin(ticks/10d)+1)/4+.25)*255);
  for(int i=0;i<10;i++){var pearl=gate.inventory.getStackInSlot(i);if(!visible(pearl))continue;var p=SkyPearlData.position(pearl);int x=(int)(p.getX()-originX),z=(int)(p.getZ()-originZ);g.pose().pushPose();g.pose().translate(gx,gz,0);g.pose().mulPose(com.mojang.math.Axis.ZP.rotation((float)Math.atan2(z-gz,x-gx)));g.fill(0,-1,(int)Math.hypot(x-gx,z-gz),1,alpha<<24|0xFFFFFF);g.pose().popPose();}
  icon(g,new net.minecraft.world.item.ItemStack(SkyPearl.ITEM.get()),gx,gz);
  java.util.List<net.minecraft.network.chat.Component> tooltip=mx>=gx-4&&mx<=gx+4&&my>=gz-4&&my<gz+4?java.util.List.of(net.minecraft.network.chat.Component.translatable("ttmisc.entrancePoint"),net.minecraft.network.chat.Component.literal("X: "+gate.getBlockPos().getX()),net.minecraft.network.chat.Component.literal("Z: "+gate.getBlockPos().getZ())):null;
  for(int i=0;i<10;i++){var pearl=gate.inventory.getStackInSlot(i);if(!visible(pearl))continue;var p=SkyPearlData.position(pearl);int x=(int)(p.getX()-originX),z=(int)(p.getZ()-originZ);icon(g,pearl,x,z);var name=pearl.has(net.minecraft.core.component.DataComponents.CUSTOM_NAME)?pearl.getHoverName():net.minecraft.network.chat.Component.translatable("ttmisc.destination");g.drawString(font,net.minecraft.network.chat.Component.literal((i+1)+": ").append(name),5,54+i*11,-1,false);if(mx>=x-4&&mx<=x+4&&my>=z-4&&my<z+4)tooltip=java.util.List.of(name,net.minecraft.network.chat.Component.literal("X: "+p.getX()),net.minecraft.network.chat.Component.literal("Z: "+p.getZ()),net.minecraft.network.chat.Component.translatable("ttmisc.distance").append(": "+SkyPearlData.distance(pearl,net.minecraft.world.phys.Vec3.atLowerCornerOf(gate.getBlockPos()),true)+"m"),net.minecraft.network.chat.Component.translatable("ttmisc.clickToTeleport"));}
  g.drawString(font,title.copy().withStyle(net.minecraft.ChatFormatting.UNDERLINE),3,40,-1,false);g.drawCenteredString(font,net.minecraft.network.chat.Component.translatable("ttmisc.numberKeys"),width/2,5,-1);g.drawCenteredString(font,net.minecraft.network.chat.Component.translatable("ttmisc.spaceToReset"),width/2,16,-1);if(tooltip!=null)g.renderComponentTooltip(font,tooltip,mx,my);
 }
 private static void icon(net.minecraft.client.gui.GuiGraphics g,net.minecraft.world.item.ItemStack pearl,int x,int z){g.pose().pushPose();g.pose().translate(x,z,0);g.pose().scale(.5f,.5f,1);g.renderItem(new net.minecraft.world.item.ItemStack(SkyPearl.ITEM.get()),-8,-8);g.pose().popPose();}
}
